    en: { title: "International & Multilingual SEO", shortLabel: "International", description: "A market-aware SEO framework for brands expanding across the US, Europe and multiple languages without creating thin country pages.", answer: "International SEO starts by deciding which markets deserve attention, then aligns keyword research, localization, URL architecture, hreflang, content and reporting. It does not mean replacing one country name with another.", pillars: [{ title: "Market selection", body: "Prioritize markets by offer fit, demand, competition, capacity and the quality of the next step." }, { title: "Localization", body: "Adapt terminology, examples, trust signals and calls to action when the market changes the answer." }, { title: "Technical clarity", body: "Keep language and regional signals consistent across URLs, canonicals, hreflang, links and sitemaps." }], process: [{ title: "Choose the market", body: "Compare search demand, SERPs, competitors and commercial readiness." }, { title: "Design the locale model", body: "Choose language and country URL rules only when the content and offer justify them." }, { title: "Localize the experience", body: "Create briefs, content, internal links and conversion paths for the selected market." }, { title: "Report by market", body: "Separate pages, countries, languages and leads so one market does not hide another." }], faq: [{ q: "Do you create a page for every European country?", a: "Only when there is a real difference in intent, language, offer, evidence or customer context. Otherwise a strong English international page is safer." }, { q: "Do you operate local offices in the US or Europe?", a: "No local office claim is made. The service is remote-first and the page explains what can be delivered honestly." }, { q: "Is hreflang enough for international SEO?", a: "No. It is one technical signal inside a broader system of useful localized content, architecture and market fit." }] },
    ar: { title: "International وMultilingual SEO", shortLabel: "دولي", description: "إطار SEO واعٍ بالسوق للتوسع في أمريكا وأوروبا واللغات المتعددة دون إنشاء صفحات دول ضعيفة أو متشابهة.", answer: "يبدأ SEO الدولي بتحديد الأسواق التي تستحق التركيز، ثم ربط بحث الكلمات والتوطين وبنية الـURL وhreflang والمحتوى والتقارير. لا يعني استبدال اسم دولة باسم دولة.", pillars: [{ title: "اختيار السوق", body: "نرتب الأسواق حسب ملاءمة العرض والطلب والمنافسة والقدرة وجودة الخطوة التالية." }, { title: "Localization حقيقي", body: "نعدّل المصطلحات والأمثلة وإشارات الثقة والدعوات عندما يغير السوق الإجابة." }, { title: "وضوح تقني", body: "نحافظ على اتساق اللغة والمنطقة في الـURLs والـcanonical وhreflang والروابط والـsitemap." }], process: [{ title: "نختار السوق", body: "نقارن الطلب ونتائج البحث والمنافسين والاستعداد التجاري." }, { title: "نصمم نموذج اللغات", body: "نختار قواعد URL للغة والدولة فقط عندما يبررها المحتوى والعرض." }, { title: "نوطن التجربة", body: "نبني Brief ومحتوى وروابط داخلية ومسارات تحويل للسوق المختار." }, { title: "نقيس حسب السوق", body: "نفصل الصفحات والدول واللغات والعملاء حتى لا تخفي دولة أداء أخرى." }], faq: [{ q: "هل تنشئون صفحة لكل دولة أوروبية؟", a: "فقط عند وجود اختلاف حقيقي في النية أو اللغة أو العرض أو الدليل أو سياق العميل. غير ذلك يستفيد من صفحة إنجليزية دولية قوية." }, { q: "هل لديكم مكاتب محلية في أمريكا وأوروبا؟", a: "لا يوجد ادعاء بمكاتب محلية. الخدمة Remote-first ويتم شرح ما يمكن تقديمه بصدق." }, { q: "هل hreflang كافٍ؟", a: "لا. هو إشارة تقنية ضمن منظومة أكبر من المحتوى المفيد والبنية وملاءمة السوق." }] },
