    en: { title: "AI SEO, AEO & GEO", shortLabel: "AI search", description: "Make important pages clearer to search engines, answer engines and generative systems while keeping the underlying content useful to people.", answer: "AI search optimization is not a shortcut around SEO. It combines strong information architecture, direct answers, evidence, entities, structured data and a clear point of view so systems can understand the page and users can trust it.", pillars: [{ title: "Answer-ready structure", body: "Organize pages around direct answers, definitions, steps, comparisons and visible questions." }, { title: "Entity and evidence clarity", body: "Make the subject, author, experience, sources and boundaries understandable without inflated claims." }, { title: "Measurement and iteration", body: "Track query classes, citations, qualified visits and conversions instead of chasing a single AI screenshot." }], process: [{ title: "Map the answer space", body: "Identify questions, entities and pages that should represent the business." }, { title: "Improve the source", body: "Rewrite structure, evidence, internal links and schema where clarity is weak." }, { title: "Test retrieval", body: "Review how important questions are answered across search and generative surfaces." }, { title: "Keep the source fresh", body: "Update facts, examples and FAQs as the offer and market change." }], faq: [{ q: "Does GEO replace traditional SEO?", a: "No. Technical SEO, useful content and authority remain the foundation; GEO adds attention to how systems retrieve and summarize information." }, { q: "Can you guarantee inclusion in AI answers?", a: "No. AI responses change by query, model, evidence and time. The work improves clarity and eligibility without promising a fixed citation." }, { q: "Should every page add an FAQ?", a: "Only when real questions help the reader. Visible, useful answers matter more than adding schema without substance." }] },
    ar: { title: "AI SEO وAEO وGEO", shortLabel: "بحث AI", description: "نجعل الصفحات المهمة أوضح لمحركات البحث ومحركات الإجابة والأنظمة التوليدية مع الحفاظ على فائدتها للقارئ.", answer: "تحسين الظهور في بحث AI ليس طريقًا مختصرًا حول SEO. هو جمع بين بنية معلومات قوية وإجابات مباشرة ودليل وكيانات وبيانات منظمة ووجهة نظر واضحة.", pillars: [{ title: "بنية جاهزة للإجابة", body: "نرتب الصفحة حول الإجابات والتعريفات والخطوات والمقارنات والأسئلة الظاهرة." }, { title: "وضوح الكيان والدليل", body: "نوضح الموضوع والخبرة والمصادر والحدود بدون ادعاءات مبالغ فيها." }, { title: "قياس وتكرار", body: "نقيس مجموعات الاستعلامات والزيارات المؤهلة والتحويلات، لا لقطة واحدة من AI." }], process: [{ title: "نرسم مساحة الإجابة", body: "نحدد الأسئلة والكيانات والصفحات التي يجب أن تمثل المشروع." }, { title: "نحسن المصدر", body: "نراجع البنية والدليل والروابط الداخلية والـSchema عندما تكون غير واضحة." }, { title: "نختبر الاسترجاع", body: "نراجع طريقة ظهور الإجابات المهمة في البحث والواجهات التوليدية." }, { title: "نحافظ على حداثة المصدر", body: "نحدث الحقائق والأمثلة وFAQ عندما يتغير العرض أو السوق." }], faq: [{ q: "هل GEO بديل عن SEO؟", a: "لا. SEO التقني والمحتوى المفيد والسلطة أساس، وGEO يضيف اهتمامًا بطريقة استرجاع الأنظمة للمعلومة وتلخيصها." }, { q: "هل تضمن الظهور في إجابات AI؟", a: "لا. الإجابات تتغير حسب الاستعلام والنموذج والدليل والوقت. نرفع الوضوح والأهلية بدون وعد باقتباس ثابت." }, { q: "هل كل صفحة تحتاج FAQ؟", a: "فقط عندما تساعد أسئلة حقيقية القارئ. الإجابات الظاهرة المفيدة أهم من إضافة Schema بلا مضمون." }] },
